function geometryBuilder(){
  const pos=[];
  const tri=(a,b,c)=>pos.push(...a,...b,...c);
  const quad=(a,b,c,d)=>{tri(a,b,c);tri(a,c,d);};
  const finish=()=>{const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.computeVertexNormals();return g;};
  return {tri,quad,finish};
}
function offsetPolygon(poly,d){
  return poly.map((p,i)=>{
    const a=poly[(i+poly.length-1)%poly.length],c=poly[(i+1)%poly.length];
    const u=[p[0]-a[0],p[1]-a[1]],v=[c[0]-p[0],c[1]-p[1]];
    const lu=Math.hypot(...u),lv=Math.hypot(...v);
    const n=[-u[1]/lu,u[0]/lu],m=[-v[1]/lv,v[0]/lv];
    const q=[p[0]+n[0]*d,p[1]+n[1]*d],r=[p[0]+m[0]*d,p[1]+m[1]*d];
    const den=u[0]*v[1]-u[1]*v[0];
    if(Math.abs(den)<1e-8)return q;
    const t=((r[0]-q[0])*v[1]-(r[1]-q[1])*v[0])/den;
    return [q[0]+u[0]*t,q[1]+u[1]*t];
  });
}
function plate(poly,depth,bev=0.004){
  const b=Math.min(bev,depth*0.32),small=offsetPolygon(poly,b),g=geometryBuilder();
  const loops=[small,poly,poly,small].map((p,i)=>p.map(q=>[q[0],q[1],[-depth/2,-depth/2+b,depth/2-b,depth/2][i]]));
  for(let k=0;k<3;k++)for(let i=0;i<poly.length;i++){const j=(i+1)%poly.length;g.quad(loops[k][i],loops[k][j],loops[k+1][j],loops[k+1][i]);}
  const cap=THREE.ShapeUtils.triangulateShape(small.map(p=>new THREE.Vector2(...p)),[]);
  for(const [a,b,c] of cap){g.tri(loops[0][c],loops[0][b],loops[0][a]);g.tri(loops[3][a],loops[3][b],loops[3][c]);}
  return g.finish();
}
function frame(outer,inner,depth,b=0.008){
  const g=geometryBuilder(),n=outer.length;
  const os=offsetPolygon(outer,b),is=offsetPolygon(inner,-b);
  const zs=[-depth/2,-depth/2+b,depth/2-b,depth/2];
  const O=[os,outer,outer,os].map((p,k)=>p.map(q=>[...q,zs[k]]));
  const I=[is,inner,inner,is].map((p,k)=>p.map(q=>[...q,zs[k]]));
  for(let k=0;k<3;k++)for(let i=0;i<n;i++){const j=(i+1)%n;g.quad(O[k][i],O[k][j],O[k+1][j],O[k+1][i]);g.quad(I[k][j],I[k][i],I[k+1][i],I[k+1][j]);}
  for(let i=0;i<n;i++){const j=(i+1)%n;g.quad(O[3][i],O[3][j],I[3][j],I[3][i]);g.quad(O[0][j],O[0][i],I[0][i],I[0][j]);}
  return g.finish();
}
function oct(w,h,c=0.035){return [[-w/2+c,-h/2],[w/2-c,-h/2],[w/2,-h/2+c],[w/2,h/2-c],[w/2-c,h/2],[-w/2+c,h/2],[-w/2,h/2-c],[-w/2,-h/2+c]];}
function group(parent,name,pos=[0,0,0],rot=[0,0,0]){const g=new THREE.Group();g.name=name;g.position.set(...pos);g.rotation.set(...rot.map(a=>a*Math.PI/180));parent.add(g);return g;}
function part(parent,name,geo,mat,pos=[0,0,0],rot=[0,0,0]){const p=createPart(name,geo,mat,{parent,position:pos,rotation:rot});p.name=name;return p;}
async function block(parent,name,s,pos,mat,r=0.06){return part(parent,name,await roundedBoxGeo(...s,Math.min(r,Math.min(...s)*0.3),{style:'chamfer'}),mat,pos);}
function panel(parent,name,w,h,d,c,pos,mat,rot=[0,0,0]){return part(parent,name,plate(oct(w,h,c),d,Math.min(d*0.25,0.025)),mat,pos,rot);}
function ring(parent,name,w,h,c,t,d,pos,mat,rot=[0,0,0]){return part(parent,name,frame(oct(w,h,c),oct(w-2*t,h-2*t,Math.max(0.02,c-t*0.6)),d,Math.min(t*0.12,d*0.18)),mat,pos,rot);}
function cyl(parent,name,r,h,pos,mat,rot=[0,0,0],seg=12,rBottom=r){return part(parent,name,cylinderGeo(r,rBottom,h,seg),mat,pos,rot);}
function beam(parent,name,a,b,r,mat,seg=8){
  const A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),len=A.distanceTo(B),mid=A.clone().add(B).multiplyScalar(.5);
  const e=new THREE.Euler().setFromQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,1,0),B.clone().sub(A).normalize()));
  return part(parent,name,cylinderGeo(r,r,len,seg),mat,mid.toArray(),[e.x,e.y,e.z].map(v=>v*180/Math.PI));
}
function tube(parent,name,points,r,mat,seg=24){
  const curve=new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(...p)),false,'catmullrom',.2);
  return part(parent,name,new THREE.TubeGeometry(curve,seg,r,8,false),mat);
}
function mergeParts(parent){
  for(const c of [...parent.children])if(!(c instanceof THREE.Mesh))mergeParts(c);
  const buckets=new Map();
  for(const c of parent.children)if(c instanceof THREE.Mesh && !Array.isArray(c.material)){const key=c.material.uuid;if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(c);}
  for(const meshes of buckets.values()){if(meshes.length<2)continue;const positions=[],normals=[];
    for(const mesh of meshes){mesh.updateMatrix();let g=mesh.geometry.clone();g.applyMatrix4(mesh.matrix);if(g.index)g=g.toNonIndexed();const p=g.getAttribute('position'),n=g.getAttribute('normal');for(let i=0;i<p.count;i++){positions.push(p.getX(i),p.getY(i),p.getZ(i));normals.push(n.getX(i),n.getY(i),n.getZ(i));}g.dispose();}
    const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));
    const combined=new THREE.Mesh(g,meshes[0].material);combined.name=parent.name+'_'+meshes[0].material.name.replace(/[^a-zA-Z0-9_-]/g,'_');parent.add(combined);for(const mesh of meshes)parent.remove(mesh);
  }
}
async function tank(parent,name,r,h,pos,m){
  const t=group(parent,name,pos);
  cyl(t,name+' base chamfer',r,0.06,[0,0.03,0],m.panel,[0,0,0],12,r*0.82);
  cyl(t,name+' ivory body',r,h-0.18,[0,0.06+(h-0.18)/2,0],m.panel);
  for(const y of [0.28,h-0.36])cyl(t,name+' orange band '+y,r*1.08,0.08,[0,y,0],m.accent);
  cyl(t,name+' shoulder',r*0.55,0.12,[0,h-0.06,0],m.panel,[0,0,0],12,r);
  cyl(t,name+' valve collar',r*0.3,0.07,[0,h+0.035,0],m.panelGray);
  return t;
}

const meta={name:'oxygen-maker',reference:'docs/style/references/generated/g02-more-props.jpg (generator)'};

// Front (+X) faces the player. Water enters on the -Z end; oxygen leaves through the tank manifold on +Z.
const SKID={x:1.5,y:0.16,z:2.6};
const BODY={x:1.2,y:1.3,z:1.35,cz:-0.5};

async function build(){
  const root=createRoot('oxygen-maker'),m=styleMaterials();
  const top=SKID.y+BODY.y;
  await block(root,'Slate skid',[SKID.x,SKID.y,SKID.z],[0,SKID.y/2,0],m.panelGray,0.06);
  for(const z of [-1.15,1.15])await block(root,'Skid foot '+z,[1.62,0.08,0.22],[0,0.04,z],m.trim,0.03);

  // Electrolyser cabinet
  const cab=group(root,'cabinet',[0,0,BODY.cz]);
  await block(cab,'Ivory electrolyser cabinet',[BODY.x,BODY.y,BODY.z],[0,SKID.y+BODY.y/2,0],m.panel,0.12);
  for(const y of [SKID.y+0.09,top-0.07])await block(cab,'Grey wrap band '+y.toFixed(2),[BODY.x+0.06,0.14,BODY.z+0.06],[0,y,0],m.panelGray,0.05);
  for(const z of [-1,1])for(const x of [-1,1])await block(cab,'Grey corner post '+x+z,[0.12,BODY.y-0.1,0.12],[x*(BODY.x/2-0.02),SKID.y+BODY.y/2,z*(BODY.z/2-0.02)],m.panelGray,0.035);

  // Front intake grille in an octagonal grey frame
  const fx=BODY.x/2+0.01;
  ring(cab,'Front intake frame',0.98,0.6,0.16,0.09,0.08,[fx,1.08,0],m.panelGray,[0,90,0]);
  panel(cab,'Front intake recess',0.82,0.44,0.03,0.11,[fx-0.015,1.08,0],m.trim,[0,90,0]);
  for(let i=0;i<4;i++)await block(cab,'Intake slat '+i,[0.05,0.045,0.74],[fx+0.005,0.94+i*0.093,0],m.panelGray,0.012);
  // Large orange service panel with a handle slot
  panel(cab,'Orange service panel',0.92,0.42,0.05,0.07,[fx+0.005,0.5,0],m.accent,[0,90,0]);
  await block(cab,'Panel handle slot',[0.04,0.06,0.36],[fx+0.04,0.58,0],m.trim,0.015);
  // Status lamp housing; the game lights the lens when the machine runs
  await block(cab,'Status lamp housing',[0.24,0.16,0.24],[0.4,top+0.08,-0.48],m.panelGray,0.04);
  await block(cab,'Status lamp lens',[0.16,0.08,0.16],[0.4,top+0.2,-0.48],m.trim,0.02);

  // Top intake fan
  cyl(cab,'Fan housing',0.4,0.14,[-0.05,top+0.07,0.05],m.panelGray,[0,0,0],12,0.43);
  cyl(cab,'Fan opening',0.33,0.02,[-0.05,top+0.145,0.05],m.trim);
  for(let i=0;i<3;i++)await block(cab,'Fan blade '+i,[0.6,0.03,0.11],[-0.05,top+0.165,0.05],m.panel,0.01).then(b=>{b.rotation.y=i*Math.PI/3;});
  cyl(cab,'Fan hub',0.08,0.06,[-0.05,top+0.18,0.05],m.accent);

  // Water inlet on the -Z end
  const w=group(root,'water_inlet',[0,0.55,BODY.cz-BODY.z/2]);
  cyl(w,'Water inlet pipe',0.07,0.32,[0,0,-0.12],m.panelGray,[90,0,0],10);
  cyl(w,'Water inlet flange',0.12,0.05,[0,0,-0.29],m.accent,[90,0,0],10);

  // Two oxygen tanks on the +Z half
  for(const [i,z] of [[0,0.55],[1,1.02]])await tank(root,'Oxygen tank '+i,0.2,1.2,[-0.1,SKID.y,z],m);
  await block(root,'Tank strap frame',[0.08,1.05,0.95],[-0.38,SKID.y+0.6,0.78],m.panelGray,0.025);
  for(const y of [0.55,1.05])await block(root,'Tank strap '+y,[0.5,0.07,0.95],[-0.1,SKID.y+y,0.78],m.panelGray,0.02);
  // Manifold from cabinet to tank valves
  const valveY=SKID.y+1.24;
  tube(root,'Oxygen manifold',[[0.1,1.2,BODY.cz+BODY.z/2-0.02],[0.1,valveY+0.1,0.2],[-0.1,valveY+0.12,0.55],[-0.1,valveY+0.12,1.02]],0.045,m.panelGray);
  cyl(root,'Orange valve wheel',0.1,0.03,[0.12,valveY+0.12,0.78],m.accent,[0,0,90],10);

  mergeParts(root);
  defineBudget({triangles:BUDGETS['medium-prop']},root);
  return root;
}
